<script setup>
import {onMounted,onUnmounted,ref} from 'vue'
import {api,live,sampleFiles,label,delay} from '../api/library.js'
const files=ref([]),page=ref(1),total=ref(0),busy=ref(false),msg=ref(''),selected=ref(null),size=ref(3),parts=ref([]),splitting=ref(false)
let alive=true;onUnmounted(()=>alive=false)
async function load(n=1){if(busy.value)return;busy.value=true;msg.value='';try{const d=live?await api(`/files?page=${n}&per_page=10`):{files:sampleFiles.slice((n-1)*10,n*10),total:sampleFiles.length,page:n};files.value=d.files;page.value=d.page;total.value=d.total;selected.value=null;parts.value=[]}catch(e){msg.value=e.message}finally{busy.value=false}}
onMounted(()=>load())
function choose(f){selected.value=selected.value===f?null:f;parts.value=[];msg.value=''}
async function split(){if(splitting.value||!selected.value)return;const f=selected.value;if(!window.confirm('分割 TXT 不消耗下载次数。开始分割？'))return;splitting.value=true;parts.value=[];try{if(!live){msg.value='演示文件没有正文，不生成真实分卷。';return}const {taskId}=await api('/novels/split',{filename:f.file_name,chunkSizeMB:size.value});while(alive){const d=await api('/novels/split/'+encodeURIComponent(taskId));if(!alive)return;if(d.status==='error')throw new Error(d.error);if(d.status==='done'){parts.value=d.outputFiles;msg.value=`已生成 ${parts.value.length} 个分卷。`;break}msg.value=`正在分卷　${d.progress}%`;await delay(800)}}catch(e){msg.value=e.message}finally{splitting.value=false}}
</script><template><section><div class="eyebrow">LIBRARY / 文件</div><h1>我的<em>文件</em></h1><button :disabled="busy||splitting" @click="load(page)">刷新列表</button><p v-if="!files.length" class="empty">{{busy?'正在读取文件…':'还没有下载记录。从番茄或七猫选一本书开始。'}}</p><article class="file panel" v-for="f in files" :key="f.source+f.file_name"><small>{{label[f.source]}}　{{f.demo?'模拟记录': f.size ? (f.size/1024).toFixed(1)+' KB' : '文件校验中'}}</small><h3>{{f.book_name}}</h3><p>{{f.author}}　{{f.mtime}}</p><div class="row"><a v-if="live" class="action" :href="`/api/${f.source==='qimao'?'qimao/':''}file/${encodeURIComponent(f.book_name)}`" download>下载文件</a><button v-if="/\.txt$/i.test(f.file_name)" :disabled="splitting" @click="choose(f)">TXT 分卷</button></div><div v-if="selected===f" class="appear"><p>最多 10 个分卷，不消耗次数。</p><label>每卷大小 <select v-model="size"><option v-for="v in [0.5,1,2,3,5,10,20]" :value="v">{{v}} MB</option></select></label> <button :disabled="splitting" @click="split">开始分割</button><p v-for="part in parts"><a :href="`/api/novels/download/${encodeURIComponent(f.file_name.replace(/\.txt$/i,''))}/${encodeURIComponent(part.name)}`" download>{{part.name}}　{{part.sizeText}}</a></p></div></article><div class="row" v-if="total>10"><button :disabled="busy||splitting||page===1" @click="load(page-1)">上一页</button>{{page}}<button :disabled="busy||splitting||page*10>=total" @click="load(page+1)">下一页</button></div><p class="notice" v-if="msg" role="status">{{msg}}</p></section></template>
